  "{topic}에서 가장 먼저 봐야 하는 건 겉으로 보이는 반응보다 반복되는 태도입니다. 이럴수록 내가 왜 신경 쓰이는지 차분하게 보면 오히려 답이 빨리 보입니다. 그래서 {topic}을 말할 때는 센 결론보다 이해되는 흐름이 더 강하게 남습니다.",
