  "{topic}에서 가장 먼저 봐야 하는 건 겉으로 보이는 반응보다 반복되는 태도입니다. 자주 반복되는 패턴은 기분 탓이 아니라 이미 관계의 방향을 보여주는 신호일 수 있습니다. 특히 {length} 안에서는 이 문장 하나가 전체 분위기를 거의 결정해줍니다.",
  "{topic}에서 가장 먼저 봐야 하는 건 겉으로 보이는 반응보다 반복되는 태도입니다. 많은 사람이 놓치는 건 결과보다 과정에서 내가 계속 불편했는지 여부입니다. 결국 {topic}에서 오래 가는 선택은 나를 덜 소모시키는 방향입니다.",
  "{topic}에서 가장 먼저 봐야 하는 건 겉으로 보이는 반응보다 반복되는 태도입니다. 많은 사람이 놓치는 건 결과보다 과정에서 내가 계속 불편했는지 여부입니다. 그래서 {topic}을 말할 때는 센 결론보다 이해되는 흐름이 더 강하게 남습니다.",
  "{topic}에서 가장 먼저 봐야 하는 건 겉으로 보이는 반응보다 반복되는 태도입니다. 많은 사람이 놓치는 건 결과보다 과정에서 내가 계속 불편했는지 여부입니다. 이 포인트만 챙겨도 {topic} 대본은 훨씬 덜 뻔하고 더 현실적으로 들립니다.",
  "{topic}에서 가장 먼저 봐야 하는 건 겉으로 보이는 반응보다 반복되는 태도입니다. 많은 사람이 놓치는 건 결과보다 과정에서 내가 계속 불편했는지 여부입니다. 한 번 이 기준으로 보면 {topic}을 바라보는 시선이 꽤 달라질 수 있습니다.",
  "{topic}에서 가장 먼저 봐야 하는 건 겉으로 보이는 반응보다 반복되는 태도입니다. 많은 사람이 놓치는 건 결과보다 과정에서 내가 계속 불편했는지 여부입니다. 생각보다 많은 답은 이미 내 감정 안에 있었고, 필요한 건 정리할 문장 하나뿐입니다.",
