  "{topic}은 의외로 큰 사건보다 사소한 습관에서 차이가 더 선명하게 드러납니다. 상대의 한마디보다 그 뒤에 이어지는 행동을 보면 생각보다 훨씬 명확합니다. 결론은 복잡하지 않습니다. {topic}은 결국 나를 편하게 만드는 방향이 맞습니다.",
